extends Control

signal play_pressed
signal settings_pressed
signal quit_pressed

@onready var play_button: Button = $CenterContainer/Panel/VBoxContainer/Play
@onready var settings_button: Button = $CenterContainer/Panel/VBoxContainer/Settings
@onready var quit_button: Button = $CenterContainer/Panel/VBoxContainer/Quit


func _ready() -> void:
	play_button.pressed.connect(_on_play_pressed)
	settings_button.pressed.connect(_on_settings_pressed)
	quit_button.pressed.connect(_on_quit_pressed)


func _on_play_pressed() -> void:
	play_pressed.emit()


func _on_settings_pressed() -> void:
	settings_pressed.emit()


func _on_quit_pressed() -> void:
	quit_pressed.emit()

extends Control

signal back_pressed

@onready var volume_slider: HSlider = $CenterContainer/Panel/VBoxContainer/VolumeSlider
@onready var resolution_option: OptionButton = $CenterContainer/Panel/VBoxContainer/ResolutionOption
@onready var fullscreen_check: CheckBox = $CenterContainer/Panel/VBoxContainer/FullscreenCheck
@onready var back_button: Button = $CenterContainer/Panel/VBoxContainer/BackButton


func _ready() -> void:
	# Read existing settings from the autoload and apply to controls
	volume_slider.value = GameSettings.volume
	resolution_option.selected = GameSettings.resolution_index
	fullscreen_check.button_pressed = GameSettings.fullscreen

	# Wire control changes -> GameSettings
	volume_slider.value_changed.connect(_on_volume_changed)
	resolution_option.item_selected.connect(_on_resolution_changed)
	fullscreen_check.toggled.connect(_on_fullscreen_toggled)

	back_button.pressed.connect(_on_back_pressed)


func _input(event: InputEvent) -> void:
	if event.is_action_pressed("ui_back"):
		_on_back_pressed()


func _on_volume_changed(value: float) -> void:
	GameSettings.set_volume(value)


func _on_resolution_changed(index: int) -> void:
	GameSettings.set_resolution_index(index)


func _on_fullscreen_toggled(button_pressed: bool) -> void:
	GameSettings.set_fullscreen(button_pressed)


func _on_back_pressed() -> void:
	back_pressed.emit()

extends Control

@onready var main_menu: Control = $MainMenu
@onready var settings_menu: Control = $SettingsMenu


func _ready() -> void:
	main_menu.visible = true
	settings_menu.visible = false

	main_menu.settings_pressed.connect(_on_main_menu_settings_pressed)
	settings_menu.back_pressed.connect(_on_settings_menu_back_pressed)


func _on_main_menu_settings_pressed() -> void:
	main_menu.visible = false
	settings_menu.visible = true


func _on_settings_menu_back_pressed() -> void:
	settings_menu.visible = false
	main_menu.visible = true

extends Control

signal back_pressed

@onready var volume_slider: HSlider = $CenterContainer/Panel/VBoxContainer/VolumeSlider
@onready var resolution_option: OptionButton = $CenterContainer/Panel/VBoxContainer/ResolutionOption
@onready var fullscreen_check: CheckBox = $CenterContainer/Panel/VBoxContainer/FullscreenCheck
